import csv

ts_map = {
    "urn:buildgraph:tsref:6041ce4e-9251-5a23-9103-a13dcc247d28": "Chiller02",
    "urn:buildgraph:tsref:af4b8334-3dca-548d-b215-2cb64a0aa2c0": "HWPump02",
    "urn:buildgraph:tsref:d8a9536c-e875-5be1-90c1-dcfdcb016492": "SupplyFan_AHU03"
}

target_date = "2018-04-02"
totals = {name: 0.0 for name in ts_map.values()}
counts = {name: 0 for name in ts_map.values()}

with open(VALUES_CSV, 'r') as f:
    reader = csv.reader(f)
    next(reader) # skip header
    for row in reader:
        ts_id, timestamp, value = row
        if timestamp.startswith(target_date):
            if ts_id in ts_map:
                name = ts_map[ts_id]
                totals[name] += float(value)
                counts[name] += 1

print(f"Totals: {totals}")
print(f"Counts: {counts}")
